/* ---- upgrade helpers: one rank costs `cost` skill points ---- */
const reach = (max = 2, cost = 1) => ({ id: 'reach', name: 'Reach', desc: '+1 range', max, cost, mod: { range: 1 } });
const potency = (pct = 20, max = 3) => ({ id: 'potency', name: 'Potency', desc: `+${pct}% power`, max, cost: 1, mod: { power: pct } });
const widen = (max = 1, cost = 2) => ({ id: 'widen', name: 'Widen', desc: '+1 area radius', max, cost, mod: { aoe: 1 } });
const thrift = (n = 2, max = 2) => ({ id: 'thrift', name: 'Thrift', desc: `−${n} mana cost`, max, cost: 1, mod: { cost: -n } });
const haste = (max = 1, cost = 2) => ({ id: 'haste', name: 'Haste', desc: '−1 cooldown', max, cost, mod: { cooldown: -1 } });
const linger = (max = 1, cost = 1) => ({ id: 'linger', name: 'Linger', desc: '+1 turn to all effects', max, cost, mod: { statusTurns: 1 } });
const virulence = (n = 15, max = 2) => ({ id: 'virulence', name: 'Virulence', desc: `+${n}% effect strength`, max, cost: 1, mod: { statusPower: n } });
const chain = (max = 2, cost = 2) => ({ id: 'chain', name: 'Arc', desc: '+1 chain target', max, cost, mod: { chain: 1 } });
const add = (id, name, desc, s, cost = 2) => ({ id, name, desc, max: 1, cost, mod: { addStatus: s } });
const addSelf = (id, name, desc, s, cost = 2) => ({ id, name, desc, max: 1, cost, mod: { addSelfStatus: s } });
